// .claude/hooks/no-dash.mjs
import { readFileSync } from 'node:fs';
const BAD = new RegExp('[' + String.fromCharCode(0x2014, 0x2013) + ']');
let input = '';
process.stdin.on('data', (c) => (input += c));
process.stdin.on('end', () => {
  let file = '';
  try { file = String(JSON.parse(input)?.tool_input?.file_path ?? ''); } catch { process.exit(0); }
  if (!file.endsWith('.md')) process.exit(0);
  let text = '';
  try { text = readFileSync(file, 'utf8'); } catch { process.exit(0); }
  const bad = text.split('\n').map((l, i) => (BAD.test(l) ? i + 1 : 0)).filter(Boolean);
  if (!bad.length) process.exit(0);
  process.stderr.write(file + ': длинное тире в строках ' + bad.join(', ') + '. Замените на "-".\n');
  process.exit(2);
});

