// tools/status.mjs
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';

const list = (dir, test) => (existsSync(dir) ? readdirSync(dir).filter(test).sort() : []);
const rules = list('.claude/rules', (n) => n.endsWith('.md'));
const agents = list('.claude/agents', (n) => n.endsWith('.md'));
const skills = list('.claude/skills', (n) => existsSync('.claude/skills/' + n + '/SKILL.md'));

if (rules.length + agents.length + skills.length === 0) {
  console.error('Все числа нули: сломан разбор, а не пустое дерево');
  process.exit(1);
}
const row = (name, a) => '| ' + name + ' | ' + a.length + ' | ' + a.join(', ') + ' |';
const text = [
  '# Состояние дерева',
  '',
  'Собрано командой node tools/status.mjs. Руками не править.',
  '',
  '| Что | Сколько | Что именно |',
  '|---|---|---|',
  row('Правила', rules),
  row('Агенты', agents),
  row('Скиллы', skills),
  ''
].join('\n');

const file = 'docs/status.md';
if (process.argv.includes('--check')) {
  const now = existsSync(file) ? readFileSync(file, 'utf8') : '';
  if (now !== text) {
    console.error('docs/status.md разошёлся с деревом. Выполните: node tools/status.mjs');
    process.exit(1);
  }
  console.log('ok');
} else {
  writeFileSync(file, text);
}
